H_SUFFIX = [" 😚", " 💗", " 🙈", " 🌚", " 😏", " 🥹"]

STOPWORDS = set("""i im i'm me my mine you your yours we us our a an the and or but is are was were be been being to of for in on at with about this that it its as do did does can could would should pls please plz very just really now hey baby babyyyy jaan ji hoon ho hai tha thi theek toh na bhi ek ki ke ka tum aap mera meri mujhe tumhe tumhari mein main hai hain se par toh aur ek h ki ko kaan""".split())

def _compose_prompt(seed: str, frame: str, suffix: str = "") -> str:
    return frame.format(seed=seed).strip() + suffix

def main() -> None:
    rows = []
    seen = set()
    for topic_index, topic in enumerate(TOPICS):
        tid, style, family, adult, anchors, seed_h, seed_hi, seed_en, hook_h, hook_hi, hook_en = topic
        prompt_sets = []
        # Hinglish has the largest share, matching Aiko's default voice.
        for i, frame in enumerate(H_FRAMES):
            for suffix_variant, suffix in enumerate(H_SUFFIX[:2]):
                prompt_sets.append(("hinglish", _compose_prompt(seed_h, frame, suffix), i * 2 + suffix_variant, hook_h))
        # Hindi and English contribute 20 rows each per topic.
        for i, frame in enumerate(HI_FRAMES):
            prompt_sets.append(("hi", _compose_prompt(seed_hi, frame), i + 60, hook_hi))
        for i, frame in enumerate(EN_FRAMES):
            prompt_sets.append(("en", _compose_prompt(seed_en, frame), i + 80, hook_en))
        assert len(prompt_sets) == 100, (tid, len(prompt_sets))
        for language, user_text, variant_index, hook in prompt_sets:
            # Ensure 5,000 literal user messages, not merely 5,000 copies of the same prompt.
            if user_text.casefold() in seen:
                user_text += f" ({tid.replace('_',' ')})"
            seen.add(user_text.casefold())
            opener_pool = OPENERS[style][language]
            closer_pool = CLOSERS[style][language]
            # Use multiple independently changing style dimensions for broad variation.
            # Cycle the closer on every row and advance the opener every full
            # closer cycle. The old multiplier pattern repeated too many answers;
            # this produces a much wider cross-product without changing topic meaning.
            opener = opener_pool[(variant_index // max(1, len(closer_pool)) + topic_index * 3) % len(opener_pool)]
            closer = closer_pool[(variant_index + topic_index * 5) % len(closer_pool)]
            assistant = f"{opener} {hook} {closer}".replace("  ", " ").strip()
            # Normalize accidental double punctuation while preserving emojis.
            assistant = assistant.replace("..", ".")
            row = {
                "id": f"RB{len(rows)+1:05d}",
                "intent": tid,
                "style": style,
                "language": language,
                "user": user_text,
                "assistant": assistant,
                "anchors": anchors,
                "adult_only": bool(adult),
                "source": "original_aiko_authored",
                "license": "Original Aiko text; no third-party dialogue included",
                "content_note": "adult themes remain non-graphic and consent-forward" if adult else "original fictional couple-chat example",
            }
            rows.append(row)
    assert len(rows) == len(TOPICS) * 100, len(rows)
    assert len({r["user"].casefold() for r in rows}) == len(rows)
    OUT.parent.mkdir(parents=True, exist_ok=True)
    with OUT.open("w", encoding="utf-8", newline="\n") as f:
        for row in rows:
            f.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")
    unique_prompts = len({r['user'].casefold() for r in rows})
    unique_replies = len({r['assistant'].casefold() for r in rows})
    language_counts = {lang: sum(1 for r in rows if r['language'] == lang) for lang in ('hinglish', 'hi', 'en')}
    adult_count = sum(bool(r['adult_only']) for r in rows)
    manifest = {
        "schema_version": 1,
        "name": "Aiko original relationship and romance conversation bank",
        "pair_count": len(rows),
        "utterance_message_count": len(rows) * 2,
        "unique_user_prompt_count": unique_prompts,
        "unique_assistant_reply_count": unique_replies,
        "topic_count": len(TOPICS),
        "language_pair_counts": language_counts,
        "adult_only_pair_count": adult_count,
        "provenance": "Original Aiko-authored examples composed from topic-specific seed prompts and language/style variants; no third-party dialogue rows included.",
        "runtime": "Local JSONL retrieval; no model, network request, or added runtime dependency.",
        "content_scope": "Fictional adult relationship chat; adult-tagged replies are suggestive and non-graphic, with consent-forward boundaries.",
    }
    manifest_path = OUT.with_name("romance_conversation_bank_manifest.json")
    manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {len(rows)} original conversation pairs ({len(rows)*2} utterance messages) to {OUT}")
    print(f"Unique user prompts: {unique_prompts}; unique assistant replies: {unique_replies}")
    print(f"Language counts: {language_counts}")
    print(f"Adult non-graphic pairs: {adult_count}")
    print(f"Manifest: {manifest_path}")

if __name__ == "__main__":
    main()
